using Autonomous146;
using CoreSim;
using Efficient152;
using Robust150;
using SharedWorldSpeedway;
using Xunit;
namespace CoreSim.Tests;
[Trait("Shard","core")]
public class EfficientContingency152Tests {
 static Tape150 Tape()=>Program150.Read<Tape150>(PhysicalSteeringAudit.PreviousPath("../robust-autonomous-racing/diagnosis-safe/A-A-original-fixed.json.gz"));
 static RiderSpec Spec()=>StandingWorld144.Rider(StartingGate.B) with{SpeedMetersPerSecond=25,ReferenceMeters=23,OffsetMeters=10};
 [Fact] public void DefaultIsOff(){Assert.Throws<InvalidOperationException>(()=>new Planner152(Spec(),false));Assert.Throws<ArgumentException>(()=>Program152.Main(Array.Empty<string>()));}
 [Theory][InlineData(false)][InlineData(true)] public void CachedPhysicalPrefixRequeuesEachCommandAndFreshPreflightDetectsCorruption(bool model){var state=Tape().States[1];var rt=new Runtime152(Spec(),model,new(ValidatedIndependent:true));rt.Begin(state.Input.Time);var a=new FreeRacingAction(-.03f,0);var b=new FreeRacingAction(.02f,1);var x=rt.Step(state,a);var y=rt.Step(state,b);Assert.Same(x.Prediction,y.Prediction);Assert.Equal(a,x.End.Input.Pending[^1].Action);Assert.Equal(b,y.End.Input.Pending[^1].Action);Assert.Equal(state.Input.Time+.24,y.End.Input.Pending[^1].ActivationAt,9);
  using(rt.Operation("independent_preflight")){var checkedStep=rt.Step(state,a);Assert.True(Bits152.Transition(x,checkedStep));Assert.NotSame(x.Prediction,checkedStep.Prediction);}rt.CorruptSearchForDiagnostics();using(rt.Operation("independent_preflight"))Assert.Throws<InvalidOperationException>(()=>rt.Step(state,a));}
 [Fact] public void IndependentGeometryMatchesFrozenInsideCrossingAndOutside(){var frame=DiagnosticWorld149.Frame();var memo=new ForecastMemo152(frame,FreeLearningExperiment.Parameters());var independent=new IndependentBoundary152(frame,memo);var fast=new Boundary152(frame);var frozen=new RacingLineGeometry(frame);var original=Tape().States[0].Input.Rider;int count=0;
  foreach(var s in new[]{0d,34.999,35,55,90,132.389,150,230,300,318.77875})foreach(var off in new[]{-3d,-1,-.4,4,10,15,19})foreach(var h in new[]{0f,.4f,1.57f}){var p=frame.At(s,off);var v=original with{Position=p.Position,Road=frame.Project(p.Position),Heading=h};var a=frozen.Clearance(v);var b=independent.Clearance(v);var c=fast.Clearance(v);Assert.Equal(BitConverter.DoubleToInt64Bits(a.Inner),BitConverter.DoubleToInt64Bits(b.Inner));Assert.Equal(BitConverter.DoubleToInt64Bits(a.Outer),BitConverter.DoubleToInt64Bits(b.Outer));Assert.Equal(a,c);count++;}Assert.Equal(210,count);}
 [Fact] public void SameStateWithDifferentWheelOrQueueCannotHitPhysicalCache(){var s=Tape().States[1];var rt=new Runtime152(Spec(),false);rt.Begin(s.Input.Time);var action=new FreeRacingAction(0,1);var x=rt.Step(s,action);var changed=s with{Input=s.Input with{Omega=s.Input.Omega+.01}};var y=rt.Step(changed,action);Assert.NotSame(x.Prediction,y.Prediction);var q=s with{Input=s.Input with{Pending=new[]{new FreeRacingCommand(s.Input.Time-.2,s.Input.Time+.04,new(.01f,0))}}};Assert.NotSame(x.Prediction,rt.Step(q,action).Prediction);}
 [Theory][InlineData(false)][InlineData(true)] public void EveryK1CandidateScoreAndForecastMatchesTheFrozenProvider(bool model){var frame=DiagnosticWorld149.Frame();var spec=Spec();var surface=MultiActionExperiment135.Surface(frame);var p=FreeLearningExperiment.Parameters();var state=Tape().States[3];var original=new Runtime150(spec,model,workBudget:false);var optimized=new Runtime152(spec,model,new(ValidatedIndependent:true));original.Begin(state.Input.Time);optimized.Begin(state.Input.Time);var a=original.Seed(state).Choice;var b=optimized.Seed(state).Choice;Assert.Equal(a.Action,b.Action);Assert.Equal(a.Candidates.Length,b.Candidates.Length);for(int k=0;k<a.Candidates.Length;k++)Assert.Equal(a.Candidates[k],b.Candidates[k]);
  foreach(var action in a.Candidates.Select(c=>c.Action)){var old=model?Limits149.FastPredictor149.Predict(state.Input,spec,frame,surface,p,147,52.72097f,.9,action,powertrain:new(omega:state.CrankOmega)):Speed148.FastPredictor148.Predict(state.Input,spec,frame,surface,p,147,52.72097f,.9,action,powertrain:new(omega:state.CrankOmega));var current=model?new ExactRuntimeB152(spec,frame,surface,p).ForecastForDiagnostics(state,action,.9):new ExactRuntimeA152(spec,frame,surface,p).ForecastForDiagnostics(state,action,.9);Assert.Equal(old.Points,current.Points);Assert.Equal(old.DistanceMeters,current.DistanceMeters);}
 }
}
